        if !response.status().is_success() {
            let status_code = response.status().as_u16();
            let body = response.into_body().await?;
            return Err(ModelListingError::api_error_with_context(
                MODEL_LISTING_PROVIDER,
                MODEL_LISTING_PATH,
                status_code,
                &body,
